    let static_abilities: Vec<_> = def
        .abilities
        .iter()
        .filter_map(|ability| match &ability.kind {
            AbilityKind::Static(static_ability) => Some(static_ability.clone()),
            _ => None,
        })
        .collect();
    let ids: Vec<_> = static_abilities
        .iter()
        .map(|ability| ability.id())
        .collect();
