fn resolve_triggers_for_source(
    game: &mut crate::game_state::GameState,
    source: ObjectId,
    event: &crate::triggers::TriggerEvent,
) -> usize {
    let triggers = crate::triggers::check_triggers(game, event);
    let matching_count = triggers
        .iter()
        .filter(|entry| entry.source == source)
        .count();
    let mut trigger_queue = crate::triggers::TriggerQueue::new();
    for trigger in triggers.into_iter().filter(|entry| entry.source == source) {
        trigger_queue.add(trigger);
    }
    if matching_count > 0 {
        crate::game_loop::put_triggers_on_stack(game, &mut trigger_queue)
            .expect("trigger should go on the stack");
        crate::game_loop::resolve_stack_entry(game).expect("trigger should resolve");
    }
    matching_count
}

fn assert_oracle_card_parses_strict(name: &str) {
    let oracle = oracle_text_by_name()
        .get(name)
        .unwrap_or_else(|| panic!("missing oracle text for regression card '{name}'"))
        .clone();
    let result = CardDefinitionBuilder::new(CardId::new(), name).parse_text(oracle.clone());
    assert!(
        result.is_ok(),
        "strict parser regression failed for '{name}': {:?}\nOracle text:\n{}",
        result.err(),
        oracle
    );
}

fn azorius_guildmage_activated_ability_matching(
    def: &CardDefinition,
    predicate: impl Fn(&crate::ability::ActivatedAbility) -> bool,
) -> &crate::ability::ActivatedAbility {
    def.abilities
        .iter()
        .find_map(|ability| {
            let AbilityKind::Activated(activated) = &ability.kind else {
                return None;
            };
            predicate(activated).then_some(activated)
        })
        .expect("Azorius Guildmage should have the requested activated ability")
}

fn azorius_guildmage_tap_ability(def: &CardDefinition) -> &crate::ability::ActivatedAbility {
    azorius_guildmage_activated_ability_matching(def, |activated| {
        activated
            .effects
            .flattened_default_effects()
            .iter()
            .any(|effect| effect.downcast_ref::<crate::effects::TapEffect>().is_some())
    })
}

fn azorius_guildmage_counter_ability(def: &CardDefinition) -> &crate::ability::ActivatedAbility {
    azorius_guildmage_activated_ability_matching(def, |activated| {
        activated
            .effects
            .flattened_default_effects()
            .iter()
            .any(|effect| {
                effect
                    .downcast_ref::<crate::effects::CounterEffect>()
                    .is_some()
            })
    })
}

fn azorius_guildmage_counter_target_filter(
    activated: &crate::ability::ActivatedAbility,
) -> &crate::target::ObjectFilter {
    let target_spec = activated
        .choices
        .first()
        .expect("counter ability should declare a target");
    let ChooseSpec::Object(filter) = target_spec.base() else {
        panic!("counter target should lower to an object filter, got {target_spec:?}");
    };
    filter
}

fn pay_azorius_guildmage_activation(
    game: &mut crate::game_state::GameState,
    player: PlayerId,
    source: ObjectId,
    activated: &crate::ability::ActivatedAbility,
    colored_mana: ManaSymbol,
) {
    game.player_mut(player)
        .expect("activating player exists")
        .mana_pool
        .add(colored_mana, 3);
    crate::cost::can_pay_cost(game, source, player, &activated.mana_cost)
        .expect("Azorius Guildmage activation cost should be payable");
    let mut dm = crate::decision::AutoPassDecisionMaker::default();
    crate::special_actions::pay_total_cost_with_choice(
        game,
        player,
        source,
        &activated.mana_cost,
        crate::costs::PaymentReason::ActivateAbility,
        &mut dm,
    )
    .expect("Azorius Guildmage activation cost should be paid");
    assert_eq!(
        game.player(player)
            .expect("activating player exists")
            .mana_pool
            .total(),
        0,
        "activation should consume the supplied colored mana for its colored and generic costs"
    );
}

#[test]
fn azorius_guildmage_strict_parser_and_compiled_text_regression() {
    assert_oracle_card_parses_strict("Azorius Guildmage");
    let def = parse_oracle_card_definition("Azorius Guildmage");
    let rendered = unprocessed_compiled_lines(&def);
    assert_eq!(
        rendered,
        vec![
            "{2}{W}: Tap target creature.",
            "{2}{U}: Counter target activated ability.",
        ],
        "Azorius Guildmage should render both activated abilities exactly"
    );

    let activated_count = def
        .abilities
        .iter()
        .filter(|ability| matches!(ability.kind, AbilityKind::Activated(_)))
        .count();
    assert_eq!(
        activated_count, 2,
        "Azorius Guildmage should have exactly two activated abilities"
    );

    let tap = azorius_guildmage_tap_ability(&def);
    let counter = azorius_guildmage_counter_ability(&def);
    assert!(
        format!("{:?}", tap.mana_cost).contains("White"),
        "tap ability should keep its white activation cost, got {:?}",
        tap.mana_cost
    );
    assert!(
        format!("{:?}", counter.mana_cost).contains("Blue"),
        "counter ability should keep its blue activation cost, got {:?}",
        counter.mana_cost
    );

    let filter = azorius_guildmage_counter_target_filter(counter);
    assert_eq!(
        filter.stack_kind,
        Some(crate::filter::StackObjectKind::ActivatedAbility),
        "counter ability should structurally target activated abilities on the stack"
    );
}

#[test]
fn azorius_guildmage_tap_activation_taps_target_creature_after_cost_payment() {
    let def = parse_oracle_card_definition("Azorius Guildmage");
    let activated = azorius_guildmage_tap_ability(&def);
    let mut game = crate::tests::test_helpers::setup_two_player_game();
    let alice = PlayerId::from_index(0);
    let bob = PlayerId::from_index(1);
    let source = game.create_object_from_definition(&def, alice, Zone::Battlefield);
    let target_def = CardDefinitionBuilder::new(CardId::new(), "Azorius Guildmage Target")
        .card_types(vec![CardType::Creature])
        .power_toughness(PowerToughness::fixed(2, 2))
        .build();
    let target = game.create_object_from_definition(&target_def, bob, Zone::Battlefield);

    pay_azorius_guildmage_activation(&mut game, alice, source, activated, ManaSymbol::White);
    let mut ctx = crate::effects::ExecutionContext::new_default(source, alice)
        .with_targets(vec![crate::effects::ResolvedTarget::Object(target)])
        .with_target_assignments(vec![crate::game_state::TargetAssignment {
            spec: activated
                .choices
                .first()
                .expect("tap ability should declare a target")
                .clone(),
            range: 0..1,
        }]);
    ctx.snapshot_targets(&game);
    for effect in activated.effects.flattened_default_effects() {
        crate::effects::execute_effect(&mut game, effect, &mut ctx)
            .expect("Azorius Guildmage tap ability should resolve");
    }

    assert!(
        game.is_tapped(target),
        "tap activation should tap the targeted creature"
    );
}

#[test]
fn azorius_guildmage_counter_activation_counters_activated_ability_only() {
    let def = parse_oracle_card_definition("Azorius Guildmage");
    let activated = azorius_guildmage_counter_ability(&def);
    let mut game = crate::tests::test_helpers::setup_two_player_game();
    let alice = PlayerId::from_index(0);
    let bob = PlayerId::from_index(1);
    let source = game.create_object_from_definition(&def, alice, Zone::Battlefield);
    let ability_source_def = CardDefinitionBuilder::new(CardId::new(), "Stack Ability Source")
        .card_types(vec![CardType::Artifact])
        .build();
    let ability_source =
        game.create_object_from_definition(&ability_source_def, bob, Zone::Battlefield);
    game.stack.push(crate::game_state::StackEntry::ability(
        ability_source,
        bob,
        vec![crate::effect::Effect::draw(1)],
    ));

    let filter = azorius_guildmage_counter_target_filter(activated);
    let filter_ctx = crate::filter::FilterContext::new(alice).with_source(source);
    assert!(
        filter.matches(
            game.object(ability_source)
                .expect("activated ability source should exist"),
            &filter_ctx,
            &game,
        ),
        "counter target filter should match an activated ability on the stack"
    );

    pay_azorius_guildmage_activation(&mut game, alice, source, activated, ManaSymbol::Blue);
    let mut ctx = crate::effects::ExecutionContext::new_default(source, alice)
        .with_targets(vec![crate::effects::ResolvedTarget::Object(ability_source)])
        .with_target_assignments(vec![crate::game_state::TargetAssignment {
            spec: activated
                .choices
                .first()
                .expect("counter ability should declare a target")
                .clone(),
            range: 0..1,
        }]);
    ctx.snapshot_targets(&game);
    for effect in activated.effects.flattened_default_effects() {
        crate::effects::execute_effect(&mut game, effect, &mut ctx)
            .expect("Azorius Guildmage counter ability should resolve");
    }

    assert!(
        game.stack.is_empty(),
        "counter activation should remove the targeted activated ability from the stack"
    );
    assert_eq!(
        game.object(ability_source)
            .expect("ability source should remain on battlefield")
            .zone,
        Zone::Battlefield,
        "countering an activated ability should not move its source permanent"
    );

    let spell_def = CardDefinitionBuilder::new(CardId::new(), "Ordinary Stack Spell")
        .card_types(vec![CardType::Instant])
        .build();
    let spell = game.create_object_from_definition(&spell_def, bob, Zone::Stack);
    game.stack
        .push(crate::game_state::StackEntry::new(spell, bob));

    let triggered_source_def =
        CardDefinitionBuilder::new(CardId::new(), "Triggered Ability Source")
            .card_types(vec![CardType::Enchantment])
            .build();
    let triggered_source =
        game.create_object_from_definition(&triggered_source_def, bob, Zone::Battlefield);
    game.stack.push(
        crate::game_state::StackEntry::ability(
            triggered_source,
            bob,
            vec![crate::effect::Effect::draw(1)],
        )
        .with_triggering_event(crate::events::RawEvent::new(
            crate::events::AbilityActivatedEvent::new(triggered_source, bob, false),
            crate::provenance::ProvNodeId::default(),
        )),
    );

    assert!(
        !filter.matches(
            game.object(spell).expect("spell stack object should exist"),
            &filter_ctx,
            &game,
        ),
        "counter target filter should reject ordinary spells"
    );
    assert!(
        !filter.matches(
            game.object(triggered_source)
                .expect("triggered ability source should exist"),
            &filter_ctx,
            &game,
        ),
        "counter target filter should reject triggered abilities"
    );
}

#[test]
fn azorius_guildmage_counter_activation_rejects_target_that_left_stack() {
    let def = parse_oracle_card_definition("Azorius Guildmage");
    let activated = azorius_guildmage_counter_ability(&def);
    let mut game = crate::tests::test_helpers::setup_two_player_game();
    let alice = PlayerId::from_index(0);
    let bob = PlayerId::from_index(1);
    let source = game.create_object_from_definition(&def, alice, Zone::Battlefield);
    let ability_source_def = CardDefinitionBuilder::new(CardId::new(), "Resolved Ability Source")
        .card_types(vec![CardType::Artifact])
        .build();
    let ability_source =
        game.create_object_from_definition(&ability_source_def, bob, Zone::Battlefield);

    pay_azorius_guildmage_activation(&mut game, alice, source, activated, ManaSymbol::Blue);
    let mut ctx = crate::effects::ExecutionContext::new_default(source, alice)
        .with_targets(vec![crate::effects::ResolvedTarget::Object(ability_source)]);
    for effect in activated.effects.flattened_default_effects() {
        let result = crate::effects::execute_effect(&mut game, effect, &mut ctx);
        assert_eq!(
            result,
            Err(crate::effects::ExecutionError::InvalidTarget),
            "counter ability should reject a target that left the stack"
        );
    }

    assert!(
        game.stack.is_empty(),
        "no stack entry should be removed when the target activated ability has already left the stack"
    );
    assert_eq!(
        game.object(ability_source)
            .expect("ability source should remain on battlefield")
            .zone,
        Zone::Battlefield,
        "invalid counter target should not move the source permanent"
    );
}

#[test]
fn irresistible_prey_strict_parser_and_compiled_text_regression() {
    let def = parse_oracle_card_definition("Irresistible Prey");
    let rendered = unprocessed_compiled_lines(&def);
    let spell_debug = format!("{:#?}", def.spell_effect);
    let compact_debug = spell_debug.split_whitespace().collect::<Vec<_>>().join(" ");

    assert_eq!(
        rendered,
        vec!["Target creature must be blocked this turn if able. Draw a card."],
        "expected exact Irresistible Prey oracle-shaped compiled text"
    );
    assert!(
        spell_debug.contains("TargetOnlyEffect")
            && spell_debug.contains("CantEffect")
            && spell_debug.contains("MustBeBlocked")
            && spell_debug.contains("DrawCardsEffect"),
        "expected direct targeted must-be-blocked restriction plus card draw, got {spell_debug}"
    );
    assert!(
        !spell_debug.contains("AddAbility") && !spell_debug.contains("RuleRestriction"),
        "Irresistible Prey must not grant a removable ability, got {spell_debug}"
    );
    assert!(
        compact_debug.contains("Target( Object(")
            && compact_debug.contains("card_types: [ Creature"),
        "expected Irresistible Prey to require a target creature, got {spell_debug}"
    );
}

fn resolve_irresistible_prey_targeting_attacker(
    blocker_tapped: bool,
) -> (
    crate::game_state::GameState,
    PlayerId,
    PlayerId,
    ObjectId,
    ObjectId,
) {
    let prey = parse_oracle_card_definition("Irresistible Prey");
    let attacker_def = CardDefinitionBuilder::new(CardId::new(), "Irresistible Prey Target")
        .card_types(vec![CardType::Creature])
        .power_toughness(PowerToughness::fixed(2, 2))
        .build();
    let blocker_def = CardDefinitionBuilder::new(CardId::new(), "Irresistible Prey Blocker")
        .card_types(vec![CardType::Creature])
        .power_toughness(PowerToughness::fixed(2, 2))
        .build();
    let draw_card = CardDefinitionBuilder::new(CardId::new(), "Irresistible Prey Draw Card")
        .card_types(vec![CardType::Creature])
        .power_toughness(PowerToughness::fixed(1, 1))
        .build();

    let mut game =
        crate::game_state::GameState::new(vec!["Alice".to_string(), "Bob".to_string()], 20);
    let alice = PlayerId::from_index(0);
    let bob = PlayerId::from_index(1);
    let source = game.create_object_from_definition(&prey, alice, Zone::Stack);
    let attacker = game.create_object_from_definition(&attacker_def, alice, Zone::Battlefield);
    let blocker = game.create_object_from_definition(&blocker_def, bob, Zone::Battlefield);
    game.create_object_from_definition(&draw_card, alice, Zone::Library);
    let hand_size_before = game.objects_in_zone(Zone::Hand).len();
    game.remove_summoning_sickness(attacker);
    if blocker_tapped {
        game.tap(blocker);
    }

    let mut ctx = crate::effects::ExecutionContext::new_default(source, alice)
        .with_targets(vec![crate::effects::ResolvedTarget::Object(attacker)]);
    ctx.snapshot_targets(&game);
    for effect in prey
        .spell_effect
        .as_ref()
        .expect("Irresistible Prey should compile to spell effects")
        .flattened_default_effects()
    {
        crate::effects::execute_effect(&mut game, effect, &mut ctx)
            .expect("Irresistible Prey spell effect should resolve");
    }

    assert!(
        game.must_be_blocked(attacker),
        "Irresistible Prey should mark the targeted creature as must-be-blocked"
    );
    assert_eq!(
        game.objects_in_zone(Zone::Hand).len(),
        hand_size_before + 1,
        "Irresistible Prey should draw a card as its second spell effect"
    );

    (game, alice, bob, attacker, blocker)
}

#[test]
fn irresistible_prey_runtime_requirement_survives_ability_removal() {
    let (mut game, alice, bob, attacker, _blocker) =
        resolve_irresistible_prey_targeting_attacker(false);

    let remove_abilities = Effect::new(crate::effects::ApplyContinuousEffect::with_spec(
        ChooseSpec::Object(crate::target::ObjectFilter::specific(attacker)),
        crate::continuous::Modification::RemoveAllAbilities,
        crate::effect::Until::EndOfTurn,
    ));
    let mut removal_ctx = crate::effects::ExecutionContext::new_default(attacker, alice);
    crate::effects::execute_effect(&mut game, &remove_abilities, &mut removal_ctx)
        .expect("remove all abilities effect should resolve");

    assert!(
        game.must_be_blocked(attacker),
        "Irresistible Prey's direct restriction should survive effects that remove abilities"
    );

    let mut combat = crate::combat_state::CombatState::default();
    crate::combat_state::declare_attackers(
        &mut game,
        &mut combat,
        vec![(attacker, crate::combat_state::AttackTarget::Player(bob))],
    )
    .expect("Irresistible Prey target should still be able to attack after ability removal");

    let missing_block = crate::combat_state::declare_blockers(&mut game, &mut combat, vec![]);
    assert!(
        matches!(
            missing_block,
            Err(crate::combat_state::CombatError::NotEnoughBlockers {
                attacker: blocked_attacker,
                required: 1,
                provided: 0,
            }) if blocked_attacker == attacker
        ),
        "Irresistible Prey should still require a block after ability removal, got {missing_block:?}"
    );
}

#[test]
fn irresistible_prey_runtime_requires_available_blocker_and_honors_if_able() {
    let (mut game, _alice, bob, attacker, blocker) =
        resolve_irresistible_prey_targeting_attacker(false);
    let mut combat = crate::combat_state::CombatState::default();
    crate::combat_state::declare_attackers(
        &mut game,
        &mut combat,
        vec![(attacker, crate::combat_state::AttackTarget::Player(bob))],
    )
    .expect("Irresistible Prey target should be able to attack");

    let missing_block =
        crate::combat_state::declare_blockers(&mut game, &mut combat.clone(), vec![]);
    assert!(
        matches!(
            missing_block,
            Err(crate::combat_state::CombatError::NotEnoughBlockers {
                attacker: blocked_attacker,
                required: 1,
                provided: 0,
            }) if blocked_attacker == attacker
        ),
        "Irresistible Prey should require a block while a blocker can block, got {missing_block:?}"
    );

    crate::combat_state::declare_blockers(&mut game, &mut combat, vec![(blocker, attacker)])
        .expect("blocking the Irresistible Prey target should satisfy the requirement");

    let (mut unable_game, _alice, unable_bob, unable_attacker, _tapped_blocker) =
        resolve_irresistible_prey_targeting_attacker(true);
    let mut unable_combat = crate::combat_state::CombatState::default();
    crate::combat_state::declare_attackers(
        &mut unable_game,
        &mut unable_combat,
        vec![(
            unable_attacker,
            crate::combat_state::AttackTarget::Player(unable_bob),
        )],
    )
    .expect("Irresistible Prey target should be able to attack in tapped-blocker branch");
    crate::combat_state::declare_blockers(&mut unable_game, &mut unable_combat, vec![])
        .expect("Irresistible Prey should not require an impossible block");
}

